{noformat}import Context from "@taxify/nodejs-common/lib/logger/Context";
import {QueryResult} from "@taxify/nodejs-common/lib/async/redshift/RedshiftConnection";
import {RedshiftPool} from "@taxify/nodejs-common/lib/async/redshift/RedshiftPool";

import {TableNames} from "./TableNames";

export interface MatchedBots {
    user_id: number;
    matches: number;
}

export class RentalsSearchCategoriesOverviewTable {

    private static readonly MAX_RESULTS = 100;

    constructor(private readonly pool: RedShiftPool) {

        public async findRentalsBotsBySpatialAndRequestFrequency(ctx: Context): Promise<QueryResult<MatchedBots>> {

            const query = `
            SELECT  
                bots.user_id,
                SUM(bots.hits_per_day) as matches,
            FROM (SELECT
                    user_id,
                    EXTRACT(DAY FROM created) AS day,
                    COUNT(*) AS hits_per_day,
                    MAX(lat) - MIN(lat) AS lat_diff,
                    MAX(lng) - MIN(lng) AS lng_diff
                FROM ${TableNames.rentalSearchCategoriesOverview}
                WHERE created >= DATE(DATEADD(DAY, -1, GETDATE()))
                GROUP BY user_id, day
                HAVING hits_per_day >= 500 and (lat_diff > 15 OR lng_diff > 15)
                ORDER BY hits_per_day DESC
                LIMIT ${RentalsSearchCategoriesOverviewTable.MAX_RESULTS}) AS bots
            GROUP BY user_id
            ORDER BY matches DESC
            LIMIT ${RentalsSearchCategoriesOverviewTable.MAX_RESULTS}
            `;

            return this.pool.selectQuery(ctx, query);


        }

    }

}{noformat}

