{noformat}import Context from "@taxify/nodejs-common/lib/logger/Context";
import Logger from "@taxify/nodejs-common/lib/logger/Logger";
import {QueryResult} from "@taxify/nodejs-common/lib/async/redshift/RedshiftConnection";
import {CompanyOrderTable} from "../table/redshift/CompanyOrderTable";
import {MatchedBots, SearchCategoriesOverviewTable} from "../table/redshift/SearchCategoriesOverviewTable";
import { MatchedBots, RentalsSearchCategoriesOverviewTable} from "../table/redshift/RentalsSearchCategoriesOverview";
import {UserInternalAsyncApi} from "@server-api-async/user/UserInternalAsyncApi";

const logger = new Logger("RobotMatcherService");

export class RobotMatcherService {
    private readonly knownBots = new Set<number>();

    constructor(
        private readonly userApi: UserInternalAsyncApi.Client,
        private readonly overviewTable: SearchCategoriesOverviewTable,
        private readonly ordersTable: CompanyOrderTable,
        private readonly rentalsOverviewTable: RentalsSearchCategoriesOverviewTable
    ) {}

    public async findAndMarkOverviewBots(ctx: Context): Promise<void> {
        const botUsers = new Set<number>();
        logger.info(ctx, `Starting search`);

        const frequencyResults = await this.overviewTable.findBotsByRequestFrequency(ctx);
        logger.info(ctx, `Search BotsByRequestFrequency`, frequencyResults);
        RobotMatcherService.addBots(botUsers, frequencyResults);

        const spatialResults = await this.overviewTable.findBotsBySpatial(ctx);
        logger.info(ctx, `Search BotsByRequestFrequency`, spatialResults);
        RobotMatcherService.addBots(botUsers, spatialResults);

        const satellites = await this.overviewTable.findBotSatellites(ctx, Array.from(botUsers.values()));
        logger.info(ctx, "Search Satellites", satellites);
        RobotMatcherService.addBots(botUsers, satellites);

        const rentalsResults = await this.rentalsOverviewTable.findRentalsBotsBySpatialAndRequestFrequency(ctx);
        logger.info(ctx, `Search RentalsBotsBySpatialAndFrequency`, rentalsResults);
        RobotMatcherService.addBots(botUsers, rentalsResults);


        const filteredOut = await this.ordersTable.findOrderAttemptsByUsers(ctx, Array.from(botUsers.values()));
        logger.info(ctx, "Users with orders to filter out", filteredOut.rows);
        const resultsFilterOut = Array.from((filteredOut.rows || []).map((el) => el.user_id));
        for (const userId of resultsFilterOut) {
            botUsers.delete(userId);
        }
        return this.markBots(ctx, botUsers);
    }

    private static addBots(botUsers: Set<number>, results: QueryResult<MatchedBots>) {
        const users = Array.from((results.rows || []).map((el) => el.user_id));
        for (const userId of users) {
            botUsers.add(userId);
        }
    }

    protected async markBots(ctx: Context, bots: Set<number>): Promise<void> {
        let newBotsFound = 0;

        for (const botId of bots) {
            if (this.knownBots.has(botId)) {
                return;
            }
            const res = await this.userApi.markUserAsBot(ctx, {user_id: botId});
            this.knownBots.add(botId);
            if (!res.is_bot_old_value) {
                newBotsFound++;
            }
        }
        logger.info(ctx, "Robots marking", {
            input: bots.size,
            new: newBotsFound
        });
    }
}{noformat}

