{noformat}USE taxify_delivery_order;
DROP PROCEDURE IF EXISTS update_in_loop_7438;

DELIMITER $$
CREATE PROCEDURE update_in_loop_7438()
BEGIN

  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 1000;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 1000;
  DECLARE v_sleep_time INT DEFAULT 5;

  SELECT 32694662, MAX(id) INTO v_min_id, v_max_id FROM taxify_delivery_order.order;

  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO
    UPDATE taxify_delivery_order.order
    SET total_price = provider_price + delivery_price + small_order_fee
    WHERE id >= 32694662 AND id <= 39519341
    AND id >= v_min_id AND id < v_min_id + v_batch_size ;


    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_max_id, 100*v_min_id/v_max_id AS completed, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;


